from mzn_bench.analysis.collect import read_csv
import matplotlib.pyplot as plt
from mzn_bench.analysis.plot import plot_all_instances
import pandas as pd 

# Read CSVs generated by mzn-bench collect-result as pandas dataframes

objs, stats = read_csv("objectives.csv", "statistics.csv")

# Get times for both configurations along with benchmark name to align them
without_proof = stats[stats.configuration.eq("Huub")][["problem", "time"]].rename(columns={"time": "time_without"})
with_proof = stats[stats.configuration.eq("Huub_Proof")][["problem", "time"]].rename(columns={"time": "time_with"})

# Merge them based on the benchmark
merged = pd.merge(without_proof, with_proof, on="problem")

# Filter rows where both times are less than 3
filtered = merged[(merged.time_without < 3) & (merged.time_with < 3)]

# Plot the results
fig, ax = plt.subplots()
ax.scatter(filtered.time_without, filtered.time_with)
ax.set_xlabel("Time without proof (s)")
ax.set_ylabel("Time with proof (s)")
ax.set_title("Scatter Plot of Times < 3s")
plt.show()